def transform(grid):
 h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]; seen=set(); objects=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   color=grid[r][c]; cells=[(r,c)]; seen.add((r,c))
   for y,x in cells:
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
      seen.add((yy,xx)); cells.append((yy,xx))
   objects.append([cells,color])
 objects.sort(key=lambda ob:min(x for y,x in ob[0]))
 changed=True
 while changed:
  changed=False
  for obj in objects:
   cells,color=obj
   for y,x in cells: out[y][x]=0
   shift=0
   while all(x-shift-1>=0 and out[y][x-shift-1]==0 for y,x in cells): shift+=1
   if shift: changed=True
   obj[0]=[(y,x-shift) for y,x in cells]
   for y,x in obj[0]: out[y][x]=color
 return out

